  const [viewBox, setViewBox] = useState(DEFAULT_VB);
  const viewBoxRef = useRef(DEFAULT_VB);
  const animFrameRef = useRef<number | null>(null);

  // Paths incrustados directamente (sin fetch, sin caché)
